{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/recipe-kits.json
    Recipe kits delivered home: a picture beside the kit name, cooking time, the ingredients list, a portions radio group and the price with an add button. Axes: layout (rows, cards), tone.
    Props (p): id, title, lead, dishes, empty, labels, portions, layout, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_dishes = ($p['dishes'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_portions = ($p['portions'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'rows')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_18}
  {if og_t(og_eq(og_len($v_dishes), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'package', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_17}
      {foreach og_l($v_dishes) as $v_d}
        {capture $c_16}
          {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_d, ['name']), 'ratio' => '4/3']])|noescape}
          {capture $c_15}
            {capture $c_3}
              {capture $c_1}
                {=og_include('icons/LucideIcon.latte', ['name' => 'timer', 'size' => 16])|noescape}
                {=og_text(og_tpl(og_get($v_labels, ['minutes']), [og_str(og_get($v_d, ['minutes']))]))}
              {/capture}
              {=og_include('compose/Badge.latte', ['variant' => 'secondary', 'size' => 'default', 'children' => (string) $c_1])|noescape}
              {if og_t(og_get($v_d, ['badge']))}
                {capture $c_2}
                  {=og_text(og_get($v_d, ['badge']))}
                {/capture}
                {=og_include('compose/Badge.latte', ['variant' => 'outline', 'size' => 'default', 'children' => (string) $c_2])|noescape}
              {/if}
            {/capture}
            {=og_include('compose/Group.latte', ['gap' => '2', 'class' => 'flex-wrap', 'children' => (string) $c_3])|noescape}
            {capture $c_6}
              {capture $c_4}
                {=og_text(og_get($v_d, ['name']))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'xl', 'weight' => 'semibold', 'children' => (string) $c_4])|noescape}
              {capture $c_5}
                {=og_text(og_get($v_d, ['summary']))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_5])|noescape}
            {/capture}
            {=og_include('compose/Stack.latte', ['gap' => '2', 'children' => (string) $c_6])|noescape}
            {capture $c_11}
              {capture $c_7}
                {=og_text(og_get($v_labels, ['ingredients']))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'children' => (string) $c_7])|noescape}
              {capture $c_10}
                {foreach og_l(og_get($v_d, ['items'])) as $v_x}
                  {capture $c_9}
                    {=og_include('icons/LucideIcon.latte', ['name' => 'check', 'size' => 16, 'class' => 'text-primary'])|noescape}
                    {capture $c_8}
                      {=og_text($v_x)}
                    {/capture}
                    {=og_include('compose/Inline.latte', ['children' => (string) $c_8])|noescape}
                  {/capture}
                  {=og_include('compose/ListItem.latte', ['class' => 'flex items-center gap-2', 'attrs' => og_attrs(['data-slot', 'items-row']), 'children' => (string) $c_9])|noescape}
                {/foreach}
              {/capture}
              {=og_include('compose/List.latte', ['tag' => 'ul', 'class' => 'grid grid-cols-1 gap-2 text-sm sm:grid-cols-2', 'attrs' => og_attrs(['data-slot', 'ingredients']), 'children' => (string) $c_10])|noescape}
            {/capture}
            {=og_include('compose/Stack.latte', ['gap' => '2', 'children' => (string) $c_11])|noescape}
            {=og_include('blocks/option-chips.latte', ['p' => ['name' => og_tpl('{0}-portions-{1}', [$v_id, og_get($v_d, ['id'])]), 'legend' => og_get($v_labels, ['portions']), 'options' => $v_portions]])|noescape}
            {capture $c_14}
              {capture $c_12}
                {=og_text(og_money(og_get($v_d, ['price']), og_get($v_d, ['currency'])))}
              {/capture}
              {=og_include('compose/Inline.latte', ['class' => 'text-xl font-bold', 'children' => (string) $c_12])|noescape}
              {capture $c_13}
                {=og_text(og_get($v_labels, ['add']))}
              {/capture}
              {=og_include('compose/Button.latte', ['variant' => 'default', 'size' => 'default', 'type' => 'button', 'ariaLabel' => og_s(og_tpl(og_get($v_labels, ['addOf']), [og_get($v_d, ['name'])])), 'children' => (string) $c_13])|noescape}
            {/capture}
            {=og_include('compose/Group.latte', ['gap' => '4', 'align' => 'center', 'justify' => 'between', 'class' => 'mt-auto', 'children' => (string) $c_14])|noescape}
          {/capture}
          {=og_include('compose/Stack.latte', ['gap' => '4', 'children' => (string) $c_15])|noescape}
        {/capture}
        {=og_include('compose/Box.latte', ['class' => og_s((og_t(og_eq($v_layout, 'cards')) ? 'rounded bg-card inset-ring inset-ring-border flex flex-col gap-4 p-4' : 'rounded bg-card inset-ring inset-ring-border grid grid-cols-1 gap-8 p-6 md:grid-cols-2')), 'attrs' => og_attrs(['data-slot', 'item']), 'children' => (string) $c_16])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Box.latte', ['class' => og_s((og_t(og_eq($v_layout, 'cards')) ? 'grid grid-cols-1 gap-8 md:grid-cols-3' : 'flex flex-col gap-8')), 'attrs' => og_attrs(['data-slot', 'items']), 'children' => (string) $c_17])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_18)])|noescape}
